  );
}
" },
    },
  },
  render: StepsExample,
};

export const Logarithmic: Story = {
  parameters: {
    docs: {
      description: { story: "Use `scale="log"` when a range spans orders of magnitude, such as frequencies, zoom levels or prices. Equal distances along the track cover equal ratios, so 20 Hz to 200 Hz takes the same width as 2 kHz to 20 kHz. A log scale needs `min` above zero and falls back to linear otherwise. Arrow keys move 1% of the track (10% with Shift), rounded onto `step` and always by at least one step. Without a `step`, values keep four significant digits. This example also shows `onValueChange` for the live value and `onValueCommitted` for the value once the drag or key press ends." },
      source: { code: "import * as React from "react";

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Slider } from "@/registry/erbium/ui/slider";

const hertz = (value: number) => (value >= 1000 ? `${value / 1000} kHz` : `${value} Hz`);

const MARKS = [20, 100, 1000, 10_000, 20_000].map((value) => ({
  label: hertz(value).replace(" ", ""),
  value,
}));

export default function SliderLogarithmicExample() {
  const [cutoff, setCutoff] = React.useState(1000);
  const [committed, setCommitted] = React.useState(1000);

  return (
    <Field className="mx-auto w-full max-w-sm gap-related">
      <div className="flex items-center justify-between gap-related">
        <FieldLabel>Cutoff</FieldLabel>
        <span className="text-caption text-muted-foreground tabular-nums">
          {hertz(cutoff)} · applied {hertz(committed)}
        </span>
      </div>
      <Slider
        value={cutoff}
        onValueChange={(value) => {
          setCutoff(value);
        }}
        onValueCommitted={(value) => {
          setCommitted(value);
        }}
        scale="log"
        min={20}
        max={20_000}
        step={1}
        marks={MARKS}
        format={{ maximumFractionDigits: 0 }}
      />
    </Field>
  );
}
" },
    },
  },
  render: LogarithmicExample,
};

